export interface GuideSection { file: string; title: string; text: string }

export const PLUGIN_GUIDE: GuideSection[] = [
 {
  "file": "guide",
  "title": "Overview",
  "text": "Noteral plugins are small JavaScript bundles that run in a sandboxed iframe and talk to the app through a versioned API (**SDK 2.3.0**). A plugin can read and edit pages (blocks, text, formatting, the cursor and selection), query and reshape databases (views, filters, sorts, properties), add commands with keyboard shortcuts, sidebar tabs, status-bar widgets, editor blocks, page-tree item types and Home widgets, restyle the app, call the network (including a local server with `network.local`), keep private data in its own storage, add `@`-style suggestion menus to the editor, expose an API to other plugins, and react to page lifecycle events. It can do only what its manifest declares and the user approved.\n\n- **[Manifest](manifest.md)**: every `manifest.json` field\n- **[Extending the interface](ui.md)**: sidebar tabs, status-bar widgets, custom blocks, custom page types, Home, appearance layers, testing\n- **[Publishing](publishing.md)**: `npm run release` and `npm run submit`, using the GitHub CLI, GitHub Releases and the community registry\n- **[Databases](../databases.md)**: views, filters, formulas, charts, custom views and embedding from code\n- **[API reference](../sdk/api-reference.md)**: every method, event, permission and type, generated from the source\n- **[llms.txt](../sdk/llms.txt)** / **[llms-full.txt](../sdk/llms-full.txt)**: the same material for coding agents"
 },
 {
  "file": "guide",
  "title": "How it fits together",
  "text": "```\nmanifest.json ──► Noteral checks id, version, sdkVersion, minAppVersion, permissions\nmain.js       ──► loaded into a sandboxed <iframe sandbox=\"allow-scripts\"> (no DOM access to the app,\n                  no Node, no same-origin storage). It talks to the app over postMessage:\n\n   this.app.pages.create({ title })  ─►  host: permission check → schema validation → handler\n                                     ◄─  result (or NoteralError with a code)\n```\n\n- Every call is checked against the permissions the user approved and validated against a JSON schema. A plugin cannot reach a method it didn't ask for.\n- A plugin that throws, hangs at startup (6 s) or in a command (30 s), or crashes its iframe is marked **failed** in *Plugins → Installed* and can be restarted. It cannot take the app down.\n- Disabling or uninstalling a plugin runs `onunload()`. It then removes every command, status item, panel, style and event listener the plugin registered."
 },
 {
  "file": "guide",
  "title": "Quick start",
  "text": "```bash\ngit clone https://github.com/neurh/noteral-plugins        # docs, SDK types, CLI, examples, registry\nnode noteral-plugins/sdk/cli/noteral-plugin.mjs init my-plugin --github   # new public repo with a working plugin\ncd my-plugin\nnpm run build                              # src/main.ts → main.js\nnpm run check                              # the store's validation, locally\nzip my-plugin.zip manifest.json main.js    # add styles.css if you have one\n```\n\nIn Noteral, open **Plugins** (puzzle icon in the left rail) → **Install from file**, then pick the zip. Review the permissions and approve. Rebuild and reinstall the zip to try a change. Installing the same id again replaces the plugin and keeps its saved data.\n\nThe starter's `src/noteral.ts` maps the SDK that the host injects at runtime (`window.Noteral`), so a standalone repo builds without installing anything. In this repo, `examples/*` import `@noteral/sdk` directly, and `sdk/tsconfig.json` maps it to `sdk/src/index.ts`. For types in your own repo, point `paths` at a Noteral checkout (see `examples/starter/README.md`)."
 },
 {
  "file": "guide",
  "title": "A complete plugin",
  "text": "```ts\nimport { Plugin, register } from \"./noteral\"; // or \"@noteral/sdk\" inside this repo\n\ninterface Data { wpm: number }\n\nclass ReadingTime extends Plugin {\n  private wpm = 230;\n\n  async onload() {\n    this.wpm = (await this.loadData<Data>()).wpm ?? 230;\n\n    this.addCommand({\n      id: \"set-speed\",\n      title: \"Reading time: set reading speed\",\n      run: async () => {\n        const answer = await this.app.ui.prompt({ title: \"Words per minute\", value: String(this.wpm) });\n        const wpm = Number(answer);\n        if (!answer || !Number.isFinite(wpm) || wpm < 50) return;\n        this.wpm = wpm;\n        await this.saveData<Data>({ wpm });\n        await this.refresh();\n      },\n    });\n\n    this.registerEvent(\"document:changed\", () => void this.refresh());\n    this.registerEvent(\"page:opened\", () => void this.refresh());\n    await this.refresh();\n  }\n\n  private async refresh() {\n    const doc = await this.app.editor.snapshot();\n    const minutes = doc ? Math.max(1, Math.round(doc.wordCount / this.wpm)) : 0;\n    await this.setStatus(\"reading-time\", doc ? `${minutes} min read` : \"\", { title: `${this.wpm} wpm` });\n  }\n}\n\nregister(ReadingTime);\n```\n\nThe full version lives in `examples/reading-time/`. `examples/meeting-notes/` shows writing into pages. Neither ships with the app; they're examples to copy."
 },
 {
  "file": "guide",
  "title": "The Plugin class",
  "text": "Extend `Plugin`, do your setup in `onload()`, and end the file with `register(YourPlugin)`. Everything registered through these helpers is disposed of automatically on unload.\n\n| Member | What it does | Needs |\n| --- | --- | --- |\n| `onload()` | Called once when the plugin starts. May be `async`; startup must finish within 6 s. | – |\n| `onunload()` | Called when the plugin is disabled, updated or uninstalled. Clean up anything you made yourself. | – |\n| `app` | The typed App API: `this.app.<namespace>.<method>(params)`. | per method |\n| `manifest` | Your parsed `manifest.json`. | – |\n| `addCommand({ id, title, description?, keywords?, shortcut?, run })` | Adds a command to the command palette (Ctrl/⌘ K) and the slash menu. `id` is local to your plugin. `run` gets a `MenuContext` when a menu item triggered it. `shortcut` binds a key, e.g. `\"Mod+Shift+K\"` (see [Shortcuts](#shortcuts)). | – |\n| `addMenuItem({ id, menu, title, icon?, kinds?, nodeTypes?, blockTypes?, danger?, run })` | Adds an item to the page, tree, block, tab or status-bar menu. `run(context)` gets what the menu was opened on. See [Menu items](ui.md#menu-items). | `menus` |\n| `getOptions()` / `defineSettings(fields)` / `onOptionsChange(fn)` | Read the user's values from your **Options** screen, add fields at runtime, react to edits. See [Options](ui.md#options). | `settings.read` |\n| `registerEvent(name, handler)` | Subscribes to an app event (see below). Returns a disposer. | event's permission |\n| `registerInterval(fn, ms)` | `setInterval` that is cleared on unload. | – |\n| `register(disposer)` | Runs a function on unload. | – |\n| `setStatus(itemId, text, { title? })` | Sets a status-bar item. An empty string hides it. | `ui.status` |\n| `setPanel(panelId, { title?, markdown, actions? })` | Renders Markdown in a right-sidebar panel, with optional buttons. | `ui.panel` |\n| `onPanelAction(panelId, handler)` | Called with the action id when a panel button is pressed. | `ui.panel` |\n| `onViewMessage(handler)` | Called with `(name, payload, view)` when one of your [HTML views](ui.md) calls `noteral.post`. | – |\n| `addStyles(css)` | Injects CSS into the app. It is removed on unload. | `ui.styles` |\n| `notify(message, kind?)` | Shows a toast (`info`, `success`, `error`). | `ui.notify` |\n| `loadData()` / `saveData(patch)` | Small settings object (≤ 64 KB) shared by all workspaces. | `settings.read` / `settings.write` |\n| `storage.get/set/delete/list/clear/usage` | Private key/value storage for larger data: any JSON up to 8 MB per key, 64 MB per plugin, per workspace or global. See [Storage](#storage). | – |\n| `readFile(path, encoding?)` | Reads a file you shipped in the bundle (`\"text\"` or `\"base64\"`). | – |\n| `registerSuggester({ id, trigger }, getItems, onSelect?)` | An inline menu when the user types `trigger` (`@`, `#`, `[`…) in a page. See [Suggesters](#suggesters). | `editor.read` |\n| `exposeApi({ name: handler })` / `callPlugin(id, method, args)` | Let other plugins call you, or call them. See [Plugins working together](#plugins-working-together). | – |\n\nStatus items and panels you want to show must also be declared under `contributes` in the manifest, so the user sees them in the review screen. Commands can be static (`contributes.commands`) or dynamic (`addCommand`). If both use the same id, `addCommand` supplies the handler.\n\n### Older plugins\n\nSDK 1.x plugins (`definePlugin((ctx) => { ... })`) still load. `ctx` keeps the old helpers (`ctx.commands.on`, `ctx.status.set`, `ctx.panels.set`, …), and `ctx.app` exposes the full 2.0 API. New plugins should use the class."
 },
 {
  "file": "guide",
  "title": "Calling the app",
  "text": "```ts\nconst page = await this.app.editor.getActive();            // ActivePage | null\nconst md   = await this.app.editor.getMarkdown({});         // whole open page as Markdown\nawait this.app.editor.insertMarkdown({ markdown: \"## Notes\\n\\n- \", position: \"cursor\" });\nconst hits = await this.app.search.query({ query: \"roadmap\", limit: 5 });\nconst { id } = await this.app.pages.create({ title: \"Retro\", markdown: \"# Retro\", open: true });\nawait this.app.databases.addRow({ databaseId, values: { Status: \"Doing\" } });\n```\n\nEvery method takes **one object** of named parameters and returns a promise. The namespaces are `app`, `editor`, `pages`, `databases`, `workspaces`, `navigation`, `tabs`, `layout`, `search`, `assets`, `settings`, `storage`, `runtime`, `plugins`, `preferences`, `appearance`, `commands`, `ui`, `clipboard` and `network`. See the [API reference](../sdk/api-reference.md) for each method's parameters, return type, permission and an example.\n\nErrors are `NoteralError` with a `code`:\n\n| code | meaning |\n| --- | --- |\n| `permission` | The manifest doesn't declare the method's permission, or the user didn't approve it. |\n| `invalid_params` | The parameters failed schema validation. The message names the field. |\n| `not_allowed` | The method isn't available to plugins, or the user declined a confirmation. |\n| `unknown_method` | No such method in this app version. Check `app.info()`'s `sdkVersion`. |\n| `cancelled`, `timeout`, `failed` | The user dismissed a dialog, the call took too long, or the handler failed. |\n\n```ts\nimport { NoteralError } from \"@noteral/sdk\";\ntry { await this.app.pages.moveToTrash({ pageId: id }); }\ncatch (e) { if (e instanceof NoteralError && e.code === \"not_allowed\") return; throw e; }\n```\n\nSome calls (moving pages to the trash, opening another workspace, resetting the appearance) always ask the user to confirm, even with the permission granted."
 },
 {
  "file": "guide",
  "title": "Events",
  "text": "| Event | Payload | Needs |\n| --- | --- | --- |\n| `document:changed` | `EditorSnapshot` (debounced) | `editor.read` |\n| `page:opened` | `ActivePage \\| null` | – |\n| `theme:changed` | `{ theme: \"light\" \\| \"dark\" }` | – |\n| `workspace:opened` | `WorkspaceInfo` | – |\n| `pages:changed` | `{ count, created, renamed, moved, deleted }` (page ids, one summary per batch) | `pages.read` |\n| `page:created` / `page:deleted` | `PageEventInfo` (`{ pageId, title, parentId, kind }`) | `pages.read` |\n| `page:renamed` | `PageEventInfo & { previousTitle }` | `pages.read` |\n| `page:moved` | `PageEventInfo & { previousParentId }` | `pages.read` |\n| `page:saved` | `{ pageId, title }`: any page's content was saved, including by other plugins (debounced) | `pages.read` |\n| `panel:action` | `{ panelId, actionId }` | `ui.panel` |\n| `settings:changed` | `{ options, changed }` (the user edited your Options) | `settings.read` |\n| `selection:changed` | `EditorSelection & { pageId }` (debounced, the open page only) | `editor.read` |\n| `layout:changed` | `LayoutInfo` (panes, tabs, sidebars; debounced) | `layout` |\n| `view:message` | Whatever your panel view posted | `ui.panel` |"
 },
 {
  "file": "guide",
  "title": "Shortcuts",
  "text": "A command can carry a keyboard shortcut, in the manifest (`\"shortcut\": \"Mod+Shift+K\"`) or in `addCommand`. `Mod` is Ctrl on Windows and Linux and ⌘ on macOS; the other modifiers are `Shift` and `Alt` (Option). Keys are letters, digits, `F1`–`F24`, arrows (`Up`, `Down`, `Left`, `Right`), `Enter`, `Space`, `Tab`, `Backspace`, `Delete`, `Home`, `End`, `PageUp`, `PageDown` and punctuation such as `/` or `.`. Matching uses the physical key, so it works on any keyboard layout.\n\nA shortcut needs `Mod` (or `Alt` with another modifier, or an `F` key), so it never takes plain typing. Shortcuts the app or the editor already uses (Ctrl/⌘ K, Z, B, I, the heading keys …) and ones another command has bound are refused: the command is not added and the error shows in the plugin's log (`commands.register` rejects with `invalid_params`), and a manifest shortcut is skipped with a warning while the command still works from the palette. For a command declared in `manifest.json`, set `shortcut` there; `addCommand` only supplies its handler. The shortcut is shown next to the command in the palette."
 },
 {
  "file": "guide",
  "title": "Editing text",
  "text": "Besides whole blocks (`editor.insertMarkdown`, `editor.updateBlock`, `editor.replaceBlocks`, `editor.removeBlocks`), SDK 2.1 can work at the cursor:\n\n```js\nconst { cursorBlockId } = await this.app.editor.getSelection();\nconst block = await this.app.editor.getBlock({ blockId: cursorBlockId }); // + parentId, prevId, nextId\nawait this.app.editor.moveBlocks({ blockIds: [block.id], direction: \"up\" }); // ids stay the same\nawait this.app.editor.insertText({ text: \"— done\" });\nawait this.app.editor.formatText({ blockIds: [block.id], styles: { bold: true, textColor: \"red\" }, mode: \"add\" });\nawait this.app.editor.select({ blockId: block.id, placement: \"end\" });\nthis.registerEvent(\"selection:changed\", (sel) => console.log(sel.text));\n```"
 },
 {
  "file": "guide",
  "title": "Storage",
  "text": "`loadData`/`saveData` is for a handful of settings. For indexes, caches, history or anything big, use `this.storage`. It needs no permission, nobody else can read it, and it is deleted with the plugin.\n\n```ts\ntype Index = Record<string, string[]>;\nconst index = (await this.storage.get<Index>(\"index\")) ?? {};   // null when missing\nawait this.storage.set(\"index\", index);                          // any JSON, ≤ 8 MB\nawait this.storage.set(\"prefs/lastQuery\", \"roadmap\", \"global\");  // shared by every workspace\nconst keys = await this.storage.list(\"prefs/\");                  // [{ key, size, modified }]\nawait this.storage.delete(\"index\");\n```\n\nScope `\"workspace\"` (the default) keeps one copy per workspace, like a vault's plugin folder; `\"global\"` is shared. Keys use letters, digits and `. _ : / @ + -`. `this.storage.usage()` reports bytes and keys against the 64 MB / 5000 key quota.\n\nFiles in your bundle (templates, dictionaries, wasm, fonts) are readable with `this.readFile(\"data/words.json\")`, or `readFile(\"model.wasm\", \"base64\")`."
 },
 {
  "file": "guide",
  "title": "Suggesters",
  "text": "A suggester adds a menu at the cursor when the user types its trigger character, the way `@` mentions or `[[` links work:\n\n```ts\nthis.registerSuggester({ id: \"people\", trigger: \"@\", minChars: 1 }, async ({ query }) =>\n  people\n    .filter((p) => p.name.toLowerCase().includes(query.toLowerCase()))\n    .map((p) => ({ title: p.name, subtitle: p.team, insert: `@${p.name}`, link: `https://people.example/${p.id}` })));\n```\n\nThe trigger and the typed query are replaced with `insert` (or the title), as a link when `link` is an `https://`, `mailto:` or `noteral://page/<id>` URL. To do something else (insert blocks, open a dialog), pass a third argument, `onSelect(item, context)`; the host then inserts nothing. `getItems` must answer within 3 s. `/` (the slash menu) and `:` (the emoji picker) are taken; add slash-menu items with `addCommand`. Up to 8 suggesters per plugin."
 },
 {
  "file": "guide",
  "title": "Plugins working together",
  "text": "A plugin can publish an API for others, the way Dataview or Tasks are used from other Obsidian plugins:\n\n```ts\n// com.example.tasks\nthis.exposeApi({\n  query: async (args: { done?: boolean }, callerId) => tasks.filter((t) => args.done === undefined || t.done === args.done),\n});\n\n// any other plugin\nconst open = await this.callPlugin<Task[]>(\"com.example.tasks\", \"query\", { done: false });\nconst running = await this.app.plugins.running(); // [{ id, name, version, methods }]\n```\n\nHandlers run inside the exposing plugin, with its permissions, so only expose what any plugin may use; the caller's id is the second argument. Arguments and results are JSON. Calls fail when the target is not running or doesn't expose the method."
 },
 {
  "file": "guide",
  "title": "Status bar widgets and popups",
  "text": "A widget can be text, an icon, a badge or a whole HTML view, and can open its own popup when clicked:\n\n```ts\nawait this.app.statusBar.setWidget({\n  id: \"pomodoro\",\n  icon: \"timer\",\n  text: \"25:00\",\n  side: \"right\",\n  width: \"auto\",          // px, \"auto\" (fit content), \"fill\" (all free space) or \"40%\"\n  minWidth: 60,\n  tone: \"accent\",         // default | accent | success | warning | danger | muted\n  progress: 0.4,          // thin bar along the bottom, 0-1\n  badge: \"3\",\n  popup: {                // opens next to the widget on click (click again closes it)\n    html: `<h3>Focus</h3><button onclick=\"noteral.post('stop')\">Stop</button>`,\n    width: 260,\n    placement: \"top-end\", // or bottom-*, left-*, right-*, *-center, center\n  },\n});\n// Cheap live updates (no reload of HTML views; they get props.data):\nsetInterval(() => this.app.statusBar.updateWidget({ id: \"pomodoro\", text: clock(), progress: done() }), 1000);\n```\n\nViews can open popovers anywhere: `noteral.popover({ html, name, toggle: true, placement: \"bottom-start\", bare: true }, \"self\")` anchors one to the calling view; other anchors are an element or rect in the view, `\"pointer\"`, `\"selection\"`, `\"status:<widgetId>\"` or `\"block:<blockId>\"`. A `name` makes the popover a singleton (`toggle` closes it on a second call), `persistent` keeps it open on outside clicks, `ui.updatePopover` changes it in place and `ui.closePopups({ name })` closes it. Popovers opened from inside a popover stay open together, like submenus."
 },
 {
  "file": "guide",
  "title": "Floating overlays",
  "text": "An overlay is an HTML view pinned above the whole app (a HUD, timer, mini player, sticky note or a full-window effect). It doesn't change the layout. It needs the `ui.overlay` permission:\n\n```ts\nconst hud = this.addOverlay({\n  id: \"now-playing\",\n  html: `<div class=\"n-card\" id=\"t\"></div><script>noteral.on(\"props\", (p) => t.textContent = p.data.title)</script>`,\n  position: \"bottom-right\", // corners, edges, center, or \"full\" (covers the window)\n  x: 16, y: 16,\n  width: 260,\n  draggable: true,          // a grip to move it (remembered; double-click resets)\n  chrome: true,             // card border and shadow\n  data: { title: \"…\" },\n});\nawait hud.update({ data: { title: \"Next song\" } });\n```\n\n`interactive: false` lets clicks pass through (decoration, confetti, focus dimming). `stack: \"top\"` puts it above menus and dialogs too; use it sparingly. Overlays are removed when the plugin unloads, and the user can close one for the session from its grip."
 },
 {
  "file": "guide",
  "title": "Custom database property types",
  "text": "Plugins can add property types to the database type picker, with their own cell look, editor and per-property options:\n\n```ts\nthis.registerPropertyType({\n  type: \"rating\",\n  title: \"Rating\",\n  icon: \"star\",\n  valueType: \"number\", // how it sorts, filters, groups and calculates: text | number | checkbox | date\n  config: [{ key: \"max\", type: \"slider\", label: \"Stars\", min: 3, max: 10, default: 5 }],\n  render: `{{#repeat config.max}}<span data-value=\"{{@number}}\" data-toggle\n    class=\"{{#if @number <= value}}on{{/if}}\">★</span>{{/repeat}}`,\n  css: `span { color: var(--text-faint); padding: 0 1px } .on { color: var(--accent) }`,\n});\n```\n\n- **Templates**: `{{value}}`, `{{text}}`, `{{config.key}}`, `{{row.title}}`, `{{property.name}}`; filters such as `{{value | percent}}`, `fixed:1`, `number`, `date`, `upper`, `truncate:20`, `default:\"—\"`, `times:100`, `clamp01`, `join:\", \"`; blocks `{{#if value >= 3}}…{{else}}…{{/if}}`, `{{#unless empty}}`, `{{#each value}}{{this}}{{/each}}` and `{{#repeat n}}{{@number}}{{/repeat}}`. Everything printed is escaped. The HTML is sanitized (no script, event handlers, forms or remote images) and shown in a shadow root styled by `css`, where theme variables work.\n- **Clicks**: in a cell, an element with `data-value=\"<json>\"` sets the value (stars, toggles, steppers, color swatches); add `data-toggle` to clear it when it's already the value. `data-edit` opens the editor.\n- **Editor**: `editor` is an HTML view shown in a popover by the cell. It gets `noteral.props` = `{ value, raw, config, property, row }`; `noteral.setData(v)` saves, `noteral.close(v)` saves and closes. Without one, the value type's own editor is used (text box, number, date picker; checkbox types toggle).\n- **Render in code**: pass a function as `render` to build the HTML in your plugin (`(ctx) => html`). It runs once per distinct value and config, and the result goes through the same sanitizer.\n- **Values**: a cell stores JSON. Store `{ value: 4, note: \"…\" }` to keep extra data next to the value that sorts and filters. Set values from code with `databases.addRow` / `updateRow` using the property's name. `databases.addProperty({ type: \"custom\", customType: \"rating\", config: { max: 10 } })` adds one.\n- If the plugin is turned off, its cells show their plain value and nothing is lost."
 },
 {
  "file": "guide",
  "title": "Limits",
  "text": "| What | Limit |\n| --- | --- |\n| One message to or from the app (call params, results, view posts) | 4 MB of JSON |\n| Calls in flight per plugin | 32; each times out after 60 s |\n| `onload` | 6 s; command handlers 30 s |\n| Commands / menu items / settings fields | 50 runtime commands, 24 menu items, 40 fields |\n| Status widgets / overlays / property types | 12 / 12 / 20 per plugin; templates 40,000 characters, 200 repeats, config 20 KB, a cell value 50 KB |\n| Block / node data | 200 KB / 1 MB per block or page |\n| HTML of one view | 400,000 characters |\n| `loadData` settings | 64 KB, 64 keys per save |\n| `storage` | 8 MB per value, 64 MB and 5000 keys per plugin |\n| `readFile` | 8 MB per file; bundle ≤ 20 MB, 400 files, entry ≤ 2 MB, `styles.css` ≤ 512 KB |\n| `network.request` | 30 s, 5 redirects, request body 4 MB, response 3 MB (then truncated) |"
 },
 {
  "file": "guide",
  "title": "Permissions",
  "text": "Ask for the smallest set that works. The install screen lists each permission with its risk level, and an update that adds permissions asks again. The full vocabulary is in the [API reference](../sdk/api-reference.md#permissions); the common ones:\n\n- **Low**: `editor.read`, `navigation`, `layout`, `menus`, `ui.status`, `ui.notify`, `ui.panel`, `ui.modal`, `settings.read`, `settings.write`, `assets.read`, `assets.write`, `workspaces.read`\n- **Medium**: `editor.write`, `pages.read`, `databases.read`, `search.read`, `ui.styles`, `ui.overlay`, `appearance`, `preferences`, `clipboard`\n- **High**: `pages.write`, `databases.write`, `workspaces.write`, `commands.execute`, `network` (any HTTP request through the app, which can send data off the device), `network.local` (`network` plus localhost and the local network, e.g. Ollama on `http://127.0.0.1:11434`)"
 },
 {
  "file": "guide",
  "title": "Styling",
  "text": "`addStyles(css)` (permission `ui.styles`) injects CSS. You can also ship a `styles.css` next to `main.js`, which is loaded the same way. Use the app's tokens so your UI follows light and dark mode: `var(--bg)`, `var(--bg-raised)`, `var(--text)`, `var(--text-soft)`, `var(--border)`, `var(--accent)`, `var(--radius-md)`, `var(--font-ui)`, `var(--font-reading)`. Call `this.app.appearance.listTokens({})` to see them all."
 },
 {
  "file": "guide",
  "title": "Debugging",
  "text": "- *Plugins → Installed* shows a failed plugin's error and a **Restart** button.\n- `console.log` in your plugin goes to the app's developer console. In server mode (`go build -tags server`), open the app in a browser and use its devtools; each plugin is a separate iframe in the frame list.\n- A call that fails with `permission` names the missing permission in its message."
 },
 {
  "file": "guide",
  "title": "Security boundary",
  "text": "- Code runs in `<iframe sandbox=\"allow-scripts\">` with an opaque origin: no access to the app's DOM, cookies, storage or Wails bindings.\n- The host checks every request against the approved permissions and validates it against the method's schema before running it.\n- The iframe's CSP is `default-src 'none'`, so a plugin can't `fetch` anything itself. Network access goes through `network.request`, which needs the `network` permission and refuses localhost and private addresses unless the plugin holds `network.local`.\n- `storage` and `readFile` only ever see the calling plugin's own data and bundle. Exposed APIs run in the exposing plugin's frame with its own permissions; a caller gains nothing it couldn't do through that plugin's public methods.\n- Installed code is stored under the data directory (`plugins/<id>/`) and is never fetched again at runtime. Updates only happen when the user presses **Update**."
 },
 {
  "file": "ui",
  "title": "ui: overview",
  "text": "SDK 2 lets a plugin add real interface rather than only Markdown panels: right-sidebar tabs, status-bar widgets, editor blocks, page-tree item types and Home widgets. Each of these is an **HTML view**, a sandboxed iframe you fill with your own HTML, CSS and script. The assistant uses the same methods, so anything it can build, a plugin can build too.\n\n| Surface | Methods | Permission |\n| --- | --- | --- |\n| Right-sidebar tab | `sidebar.setTab`, `removeTab`, `openTab`, `setLayout`, `moveTab`, `list` | `ui.panel` (layout calls: `layout`) |\n| Status-bar widget | `statusBar.setWidget`, `removeWidget`, `list` | `ui.status` |\n| Editor block | `blocks.registerType`, `unregisterType`, `listTypes`, `insert`, `setData` | `blocks` (`insert`/`setData`: `editor.write`) |\n| Page-tree item type | `nodes.registerType`, `unregisterType`, `listTypes`, `create`, `getData`, `setData` | `nodes` (`create`/`setData`: `pages.write`) |\n| Home | `home.listViews`, `createView`, `updateView`, `setBackground`, `addWidget`, `updateWidget`, … | `home` |\n| Appearance | `appearance.setTokens`, `styleComponent`, `addCss`, `removeCss`, `reset`, `listLayers`, `setLayer` | `appearance` |\n| Databases | `databases.embed`, `addView`, `updateView`, `queryView`, `addProperty`, `updateProperty`, `checkFormula`, … | `databases.read` / `databases.write` |\n\nEverything a plugin contributes belongs to it. Disabling or uninstalling the plugin removes all of it, and none of it can touch another plugin's contributions."
 },
 {
  "file": "ui",
  "title": "A sidebar tab",
  "text": "```ts\nimport { Plugin, register } from \"@noteral/sdk\";\n\nclass Tasks extends Plugin {\n  async onload() {\n    await this.app.sidebar.setTab({\n      id: \"tasks\",\n      title: \"Tasks\",\n      icon: \"list-checks\",           // any lucide icon name\n      html: `\n        <div class=\"n-col\">\n          <h3>Open tasks</h3>\n          <ul class=\"n-list\" id=\"list\"></ul>\n          <button class=\"primary\" id=\"refresh\">Refresh</button>\n        </div>\n        <script>\n          async function load() {\n            const hits = await noteral.app.search.query({ query: \"TODO\", limit: 20 });\n            list.innerHTML = hits.map((h) => '<li><a data-id=\"' + h.pageId + '\">' + h.title + '</a></li>').join(\"\");\n          }\n          list.onclick = (e) => e.target.dataset.id && noteral.open(e.target.dataset.id);\n          refresh.onclick = load;\n          noteral.on(\"pages:changed\", load);\n          load();\n        </script>`,\n      open: true,\n    });\n  }\n}\nregister(Tasks);\n```\n\n`markdown` + `actions` still work for simple panels. Pass `split: true` to open the tab in a new stacked group under the current one. Users can drag tabs between groups. `sidebar.setLayout({ groups: [{ tabs: [...], size: 0.6 }, …] })` arranges them from code. Built-in tab keys are `outline`, `backlinks`, `info` and `assistant`. Contributed tabs are keyed `plugin:<pluginId>:<id>`."
 },
 {
  "file": "ui",
  "title": "The view runtime",
  "text": "Every HTML view gets `window.noteral`:\n\n| Member | What it does |\n| --- | --- |\n| `noteral.props` | What the host passed in. Blocks, nodes and Home widgets get `{ data, … }`. |\n| `noteral.app.<ns>.<method>(params)` | The App API, limited to the owner's approved permissions. |\n| `noteral.setData(data)` | Saves the view's data. For blocks, nodes and Home widgets it is stored in the document. |\n| `noteral.onProps(fn)` / `onTheme(fn)` | Called when the data changes or when light/dark switches. |\n| `noteral.on(event, fn)` | App events (`document:changed`, `pages:changed`, …). |\n| `noteral.post(name, payload)` | Sends a message to your plugin, which receives it as the `view:message` event. |\n| `onMessage(fn)` | Receives `views.post(...)` messages from your plugin. |\n| `noteral.open(target)` | Opens a page id, `noteral://page/<id>` or an `https://` URL. |\n| `noteral.popover(opts, at)` | Opens an HTML popover anchored to `at`: an element, a rect, `\"self\"` (this view), `\"pointer\"`, `\"selection\"`, `\"status:<widgetId>\"` or `\"block:<id>\"`. Resolves with the value the popover closes with. |\n| `noteral.menu(items, at)` / `contextMenu(items, event)` | A native menu; resolves with the picked item's id. |\n| `noteral.modal(opts)` | An HTML dialog; resolves with its close value. |\n| `noteral.close(value)` | Closes the popover, dialog or editor this view is in, returning `value`. |\n| `noteral.resize()` | Measures the content again (height, and width in the status bar). |\n\nViews follow the app's theme automatically. Every token (`--bg`, `--text`, `--accent`, `--border`, `--radius-md`, `--font-ui`, …) is defined inside the frame. A small kit is also built in: `.n-card`, `.n-row`, `.n-col`, `.n-grid`, `.n-list`, `.n-chip`, `.n-muted`, `.n-faint`, and buttons with `.primary` / `.ghost`. Height follows the content (it grows and shrinks) unless the surface fills its space (full custom pages, Home widgets).\n\n**Your CSS always wins.** The kit lives in a cascade layer (`@layer noteral`) and uses zero-specificity `:where()` selectors, so any rule you write overrides it, with no `!important` needed. The frame itself is **transparent**: `html` and `body` have no background, and the iframe follows the app's color scheme, so the browser doesn't paint a white or black canvas behind a view. If you want a card, give it a background yourself (`background: var(--bg-elevated)`).\n\n**Surfaces.** `noteral.surface` (also `<html data-surface=\"…\">`) tells a view where it is drawn: `page`, `block`, `sidebar`, `status`, `home`, `panel`, `popover` or `overlay`. `noteral.fill` is `true` when the view should fill its box. Use them to adapt one view to several places:\n\n```css\nhtml[data-surface=\"status\"] body { font-size: 12px; }   /* the kit is already compact there */\nhtml[data-surface=\"page\"] main { max-width: 960px; margin: 0 auto; }\n```\n\nA view's iframe is `sandbox=\"allow-scripts\"` and has a CSP with no network access. It can't reach the app's DOM, storage or the internet. Anything outside the frame goes through `noteral.app`."
 },
 {
  "file": "ui",
  "title": "Custom blocks",
  "text": "```ts\nawait this.app.blocks.registerType({\n  type: \"counter\",\n  title: \"Counter\",\n  description: \"A number you can bump\",\n  icon: \"plus-circle\",\n  defaultData: { count: 0 },\n  height: 64,\n  html: `<button class=\"primary\" id=\"b\"></button>\n    <script>\n      const paint = () => b.textContent = \"Clicked \" + (noteral.props.data.count || 0) + \"×\";\n      b.onclick = () => noteral.setData({ count: (noteral.props.data.count || 0) + 1 });\n      noteral.onProps(paint); paint();\n    </script>`,\n});\n```\n\nThe block shows up in the slash menu under its title. Its data is saved in the page (as a `custom` BlockNote block with `kind` and JSON `data`), so it is exported and synced with the document. `blocks.insert({ type, data })` adds one from code."
 },
 {
  "file": "ui",
  "title": "Custom page types",
  "text": "`nodes.registerType({ type, title, icon, html, defaultData, layout })` adds an entry to the **New** menu in the page tree. `noteral.setData` persists an item's data (up to 1 MB). You can use this for boards, timers, sketches, dashboards, or anything that isn't a document.\n\n| `layout` | What the item opens as |\n| --- | --- |\n| `\"full\"` (default) | Your view takes the **whole pane**: no title, cover or icon, and one scroll area (yours). `noteral.fill` is `true`. Size your root to `height: 100vh` and scroll inside it. |\n| `\"page\"` | A normal page head (title, icon, cover) with your view under it at its natural height, scrolling with the page. Use this when the item reads like a document. |\n\n```ts\nawait this.app.nodes.registerType({\n  type: \"kanban\",\n  title: \"Board\",\n  icon: \"lucide:kanban\",\n  layout: \"full\",\n  defaultData: { columns: [{ title: \"To do\", cards: [] }] },\n  html: `<style>\n      body { margin: 0; height: 100vh; display: flex; gap: 12px; padding: 16px; overflow-x: auto; }\n      .col { flex: 0 0 260px; background: var(--bg-sunken); border-radius: var(--radius-md); padding: 10px; }\n    </style>\n    <div id=\"board\"></div>\n    <script>/* render noteral.props.data, save with noteral.setData */</script>`,\n});\n```\n\nThe item's title still shows in the page tree, tabs and search. In a `full` view you can show it yourself from `noteral.props.title`."
 },
 {
  "file": "ui",
  "title": "Menu items",
  "text": "Plugins can add items to five app menus: `page` (the ⋯ menu in a page header), `tree` (right-click in the page tree), `block` (the block handle menu), `tab` (a tab's context menu) and `status` (right-click on the status bar). Each item runs one of the plugin's commands, which receives a `MenuContext` describing what the menu was opened on.\n\n```ts\nthis.addMenuItem({\n  id: \"word-count\",\n  menu: \"block\",\n  title: \"Count words in block\",\n  icon: \"lucide:hash\",\n  blockTypes: [\"paragraph\", \"heading\"],\n  run: async ({ pageId, blockId }) => {\n    const text = await this.app.editor.getMarkdown({ pageId, blockIds: [blockId!] });\n    await this.app.ui.notify({ message: `${text.split(/\\s+/).filter(Boolean).length} words` });\n  },\n});\n```\n\n| `MenuContext` field | Set for |\n| --- | --- |\n| `menu` | Always: which menu it was. |\n| `pageId`, `kind` (`page` · `folder` · `database` · `custom`) | Page, tree and tab menus; the page of a block. |\n| `nodeType` | When `kind` is `custom`. |\n| `blockId`, `blockType` | Block menu. A custom block's type is its registered `type`. |\n| `tabKey` | Tab menu. |\n\nFilter where an item appears with `kinds`, `nodeTypes` and `blockTypes`. Set `danger: true` for destructive actions (shown in red). Items can also be declared in the manifest (`contributes.menus`) so they show before the plugin loads. `menus.addItem` / `menus.removeItem` / `menus.list` do the same through the App API, which is what the assistant uses. Needs the `menus` permission."
 },
 {
  "file": "ui",
  "title": "Options",
  "text": "Give users settings without building a screen. Declare fields in `contributes.settings` (or at runtime with `this.defineSettings([...])`) and they appear under **Plugins → Installed → Options** (the sliders button on the plugin's row), grouped by `section`, with a *Reset to defaults* button.\n\n```ts\nconst options = await this.getOptions<{ format: string; notify: boolean }>();\nthis.onOptionsChange((next, changed) => {\n  if (changed.includes(\"format\")) this.refresh(next.format as string);\n});\n```\n\nField types are `toggle`, `text`, `textarea`, `number`, `slider` (`min`/`max`/`step`), `select` (`options: [{ value, label }]`) and `color`. Values are saved with the plugin's data, coerced to the field's type, and missing values fall back to `default`. Each change raises the `settings:changed` event. `getOptions` needs `settings.read`."
 },
 {
  "file": "ui",
  "title": "Status-bar widgets",
  "text": "```ts\nawait this.app.statusBar.setWidget({ id: \"clock\", text: \"12:00\", icon: \"clock\", side: \"right\", order: 5 });\n// or a live HTML widget; width is px, \"auto\" (fits its content), \"fill\" (takes the free space) or \"40%\":\nawait this.app.statusBar.setWidget({ id: \"pomodoro\", html: \"<span id=t>25:00</span><script>…</script>\", width: \"auto\", minWidth: 60 });\n// a popup next to the widget, opened and closed by clicking it:\nawait this.app.statusBar.setWidget({ id: \"sync\", icon: \"cloud\", tone: \"success\", badge: \"2\", popup: { html: \"<h3>Sync</h3>…\", width: 280 } });\nawait this.app.statusBar.updateWidget({ id: \"sync\", progress: 0.6, text: \"60%\" }); // merge a change\n```\n\nSet `command` on a text widget to run one of your commands when it's clicked. The command receives `{ source: \"status\", widget, anchor }`, so it can open a popover at `anchor`. See [Status bar widgets and popups](README.md#status-bar-widgets-and-popups) for every option, [Floating overlays](README.md#floating-overlays) and [Custom database property types](README.md#custom-database-property-types)."
 },
 {
  "file": "ui",
  "title": "Home",
  "text": "Home views are grids of widgets on a background. With `home`, a plugin can create a view (`createView`), change its layout (`updateView`, including view-level `css`), set the background (presets, a solid color or a gradient), and add widgets. Widget types include notes, clocks, quick links, pages and an `html` widget, which is a view like the ones above and can persist its data. `home.widgetTypes()` lists them all."
 },
 {
  "file": "ui",
  "title": "Appearance layers",
  "text": "Style changes are stored as **layers**, which the user can inspect, turn off or remove under *Plugins → Created*. A plugin's tokens, component styles and CSS go into its own layer, `plugin:<id>`, which is removed when the plugin is uninstalled.\n\n```ts\nawait this.app.appearance.setTokens({ light: { accent: \"#2f6f5e\" }, dark: { accent: \"#7cc4ae\" } });\nawait this.app.appearance.styleComponent({ component: \"sidebar\", rules: { background: \"var(--bg-sunken)\" } });\n```\n\n`appearance.listTokens()` and `appearance.listComponents()` return the names you can target."
 },
 {
  "file": "ui",
  "title": "Databases",
  "text": "Everything about a database is addressed by **name**: properties, options and view settings take the names the user sees (ids work too), and reads return names.\n\n**Embedding.** `databases.embed({ pageId, databaseId?, title?, properties?, view?, position?, blockId? })` puts a database block in a page. With `databaseId` it links an existing database (any database in the workspace); without it, it creates a new database inside the page. `position` is `start`, `end` (default), `before` or `after` a `blockId` (or `anchor` text). It works whether or not the page is open. In the Markdown that `pages.get`, `pages.read` and `editor.getMarkdown` return, an embedded database is a line `<!-- database:<id> Title -->` and a custom block is `<!-- block:<blockId> kind -->`. Keep those lines when you write the Markdown back and the blocks survive; move them to move the blocks, delete them to remove them. A new `<!-- database:<id> -->` line also embeds that database.\n\n**Views.** `addView` / `updateView` take `type` (`table`, `board`, `list`, `gallery`, `calendar`, `chart`, `custom`) and only the settings you pass:\n\n- `filters` + `filterMode` (simple rules) and `advanced` (`{ mode: \"and\" | \"or\", items }`, where items are rules `{ property, op, value }` or nested groups, up to 4 levels). Both apply together. Date rules accept ISO dates, relative dates (`@today`, `@weekAgo`, …) and `within` ranges (`pastWeek`, `thisMonth`, …).\n- `groupBy` on boards (select, multi-select, status, checkbox) and on tables, lists and galleries (any property), with `hiddenGroups`, `collapsedGroups`, `hideEmptyGroups`, `colorColumns`.\n- `show` / `hide` / `order` / `widths` / `calcs`, `rowNumbers`, `wrap`, `showIcons`, `cardPreview`, `cardSize` (`small`, `medium`, `large`), `showFilterBar`, `limit` (rows before *Load more*), and `openIn` — where a row opens: `modal` (default), `side`, `tab` or `current`.\n- `chart` for chart views: `{ kind, x, dateBucket, aggregate, y, series, stacked, normalize, cumulative, sort, limit, omitEmpty, smooth, labels, legend, grid, palette, height, goal, yMin, yMax, format, title }`. `kind` is bar, column, line, area, pie, donut, scatter, funnel, radar, heatmap or number; `aggregate` is count, countValues, countUnique, sum, average, median, min or max (the last five need a numeric `y`). `x` can also be `createdTime` or `lastEdited`. Passed fields merge into the current chart.\n- `custom` for custom views: `{ html, height? }`, a fully custom HTML/CSS/JS view in a sandboxed frame. Its script reads `window.noteral.database`:\n\n```js\nconst db = window.noteral.database;\n// db.schema, db.view, db.rows — rows have id, title, icon, values (by property name) and cells (display text)\ndb.onChange((data) => render(data.rows));    // called with fresh { schema, view, rows } when the database changes\ndb.openRow(rowId);                            // open a row\nawait db.setValue(rowId, \"Status\", \"Done\");   // change one value (by property name)\nawait db.addRow({ Name: \"New\", Status: \"Todo\" });\n```\n\n`getView` returns every setting with property names, and `queryView` reads rows the way a view shows them (plus optional extra `filters`, `advanced`, `sorts`, `search`).\n\n**Formulas.** A property of type `formula` computes its value from the row: `addProperty({ databaseId, name: \"Left\", type: \"formula\", formula: 'dateBetween(prop(\"Due\"), now(), \"days\")', format?, dateFormat? })`. Refer to properties with `prop(\"Name\")`. Formulas are checked when saved; an error names the problem and the offending part. `checkFormula({ databaseId, formula })` tries one without saving and returns its result type and sample values, and `formulaFunctions()` lists every function, one per line. Row reads include formula results (with `errors` per row when one fails); setting a formula value is an error. Renaming a property updates the formulas that use it, and `updateProperty({ type: \"formula\", formula })` turns an existing property into a formula."
 },
 {
  "file": "ui",
  "title": "Testing before you ship",
  "text": "`plugins.test({ manifest, code, styles })` runs a plugin in a throwaway frame and reports `{ ok, error, logs, contributions }` without installing it. `plugins.logs({ id })` returns a running plugin's recent console output and errors. The assistant runs every plugin it writes through `plugins.test` before installing it, and it fixes and retries when the test fails."
 },
 {
  "file": "manifest",
  "title": "manifest: overview",
  "text": "Every plugin ships a `manifest.json` next to its entry file. Noteral validates it on install and on every update. A manifest that fails validation is rejected with a message naming the field.\n\n```json\n{\n  \"id\": \"com.example.reading-time\",\n  \"name\": \"Reading Time\",\n  \"version\": \"2.0.0\",\n  \"sdkVersion\": \"2.0.0\",\n  \"minAppVersion\": \"0.2.0\",\n  \"description\": \"Shows how long the open page takes to read.\",\n  \"author\": \"Ada Example\",\n  \"authorUrl\": \"https://example.com\",\n  \"repo\": \"ada/noteral-reading-time\",\n  \"entry\": \"main.js\",\n  \"permissions\": [\"editor.read\", \"ui.status\", \"settings.read\", \"settings.write\"],\n  \"contributes\": {\n    \"commands\": [{ \"id\": \"set-speed\", \"title\": \"Reading time: set reading speed\", \"keywords\": \"wpm words\", \"shortcut\": \"Mod+Alt+R\" }],\n    \"statusItems\": [{ \"id\": \"reading-time\", \"label\": \"Reading time\" }],\n    \"panels\": [{ \"id\": \"reading-stats\", \"title\": \"Reading stats\" }]\n  }\n}\n```"
 },
 {
  "file": "manifest",
  "title": "Fields",
  "text": "| Field | Required | Rules |\n| --- | --- | --- |\n| `id` | yes | Reverse-domain, lowercase: `^[a-z][a-z0-9]*(\\.[a-z0-9][a-z0-9-]*)+$`, at most 100 characters. **Never change it**: it is the key for updates and saved data. |\n| `name` | yes | Shown in the store, at most 80 characters. |\n| `version` | yes | Semver `MAJOR.MINOR.PATCH` (pre-release suffixes allowed). Updates compare this against the installed version. |\n| `sdkVersion` | yes | The SDK you built against. This app accepts majors **1** and **2**. Use `\"2.0.0\"`. |\n| `minAppVersion` | no | The oldest Noteral version that can run the plugin. Older apps refuse to install it and explain why. |\n| `description` | no | One or two sentences, at most 500 characters. |\n| `author`, `authorUrl` | no | Shown in the store and on the review screen. |\n| `repo` | for the community store | GitHub `owner/name` the releases come from. Must match the registry entry. |\n| `entry` | yes | The bundled script, normally `main.js`. One file; no imports at runtime. |\n| `permissions` | yes | Array from the vocabulary below. Use `[]` when you need none. Unknown names are rejected. |\n| `contributes` | no | Static UI surfaces, listed on the review screen (see below). |\n\nOlder plugins may ship `plugin.json` instead of `manifest.json`. It is still read, but new plugins should use `manifest.json`."
 },
 {
  "file": "manifest",
  "title": "contributes",
  "text": "| Key | Entry fields | Notes |\n| --- | --- | --- |\n| `commands` | `id` (`^[a-z][a-z0-9-]{1,48}$`), `title`, `description?`, `keywords?` (a space-separated string), `shortcut?` (e.g. `\"Mod+Alt+R\"`, max 40 characters; see [Shortcuts](README.md#shortcuts)) | Appear in the command palette and slash menu before the plugin loads. A shortcut that clashes with the app or another command is skipped with a warning. Handle them with `this.addCommand({ id, ... , run })` (same id). |\n| `statusItems` | `id`, `label`, `description?` | Space in the status bar, filled with `this.setStatus(id, text)`. |\n| `panels` | `id`, `title`, `description?` | A right-sidebar panel, filled with `this.setPanel(id, { markdown, actions })`. |\n| `menus` | `id`, `menu` (`page` · `tree` · `block` · `tab` · `status`), `title`, `command`, `icon?`, `kinds?`, `nodeTypes?`, `blockTypes?`, `danger?` | An item in an app menu. Choosing it runs the plugin's `command` and passes it a `MenuContext` (see [ui.md](ui.md#menu-items)). Needs `menus`. |\n| `settings` | `key`, `type` (`toggle` · `text` · `textarea` · `number` · `slider` · `select` · `color`), `label`, `description?`, `section?`, `placeholder?`, `default?`, `options?` (select), `min?` / `max?` / `step?` | Fields on the plugin's **Options** screen. Read them with `this.getOptions()`. |\n\nCommands added only through `addCommand` don't need a manifest entry. Declaring them is still nice, because users see them before they install.\n\n```json\n\"contributes\": {\n  \"commands\": [{ \"id\": \"copy-link\", \"title\": \"Copy link to page\" }],\n  \"menus\": [{ \"id\": \"copy-link\", \"menu\": \"tree\", \"title\": \"Copy link\", \"icon\": \"lucide:link\", \"command\": \"copy-link\", \"kinds\": [\"page\"] }],\n  \"settings\": [\n    { \"key\": \"format\", \"type\": \"select\", \"label\": \"Link format\", \"default\": \"markdown\",\n      \"options\": [{ \"value\": \"markdown\", \"label\": \"Markdown\" }, { \"value\": \"url\", \"label\": \"Plain URL\" }] },\n    { \"key\": \"notify\", \"type\": \"toggle\", \"label\": \"Show a toast after copying\", \"default\": true }\n  ]\n}\n```"
 },
 {
  "file": "manifest",
  "title": "Permissions",
  "text": "| Permission | Allows | Risk |\n| --- | --- | --- |\n| `editor.read` | Read the open page's text, blocks, selection; `document:changed` | low |\n| `editor.write` | Insert, replace, update and remove blocks in the open page | medium |\n| `pages.read` | List and read any page, favorites, recent, backlinks, trash | medium |\n| `pages.write` | Create, rename, move, duplicate, trash and restore pages; write content | high |\n| `databases.read` | List databases, read schemas, query rows | medium |\n| `databases.write` | Create databases, add properties, add/update rows | high |\n| `workspaces.read` | List workspaces and read the current one | low |\n| `workspaces.write` | Create, rename and switch workspaces (switching always asks the user) | high |\n| `navigation` | Open pages and Home, go back and forward, list and close tabs | low |\n| `layout` | Split panes, toggle panels, open overlays | low |\n| `search.read` | Full-text search across the workspace | medium |\n| `assets.read` / `assets.write` | Pick images and files through the system dialog | low |\n| `settings.read` / `settings.write` | The plugin's own saved data (`loadData` / `saveData`) | low |\n| `preferences` | Read and change app preferences (font size, width, …) | medium |\n| `appearance` | Change theme tokens, style components, add CSS | medium |\n| `commands.execute` | List and run app and plugin commands | high |\n| `menus` | Add items to the page, tree, block, tab and status-bar menus | low |\n| `clipboard` | Read and write clipboard text | medium |\n| `network` | HTTP requests through the app (no localhost or private ranges) | high |\n| `ui.status`, `ui.notify`, `ui.panel`, `ui.modal` | Status items, toasts, panels, confirm/prompt/pick dialogs | low |\n| `ui.styles` | Inject CSS into the app | medium |\n\nThe generated [API reference](../sdk/api-reference.md) lists which methods each permission unlocks. Its source of truth is `PERMISSIONS` in `frontend/src/sdk-host/spec.ts`, and the Go validator (`internal/plugins/plugins.go`) mirrors the same list."
 },
 {
  "file": "manifest",
  "title": "Release files",
  "text": "A release (or a zip for *Install from file*) contains:\n\n| File | Required | Limit |\n| --- | --- | --- |\n| `manifest.json` | yes | 256 KB |\n| the `entry` file (`main.js`) | yes | 2 MB |\n| `styles.css` | no | 512 KB; loaded with the plugin, removed on unload |\n\nA zip for *Install from file* may hold at most 400 files and 20 MB, and each file at most 5 MB."
 }
];

/** Return and parameter types of the App API, by name. */
export const PLUGIN_TYPES: Record<string, string> = {
 "AppInfo": "export interface AppInfo {\n  appName: string;\n  appVersion: string;\n  sdkVersion: string;\n  platform: string;\n  theme: \"light\" | \"dark\";\n  workspaceId: string | null;\n}",
 "ActivePage": "export interface ActivePage {\n  id: string;\n  title: string;\n  kind: \"page\" | \"folder\" | \"database\" | \"row\" | \"custom\";\n  paneId: string;\n  /** True when the page is open in a live editor (editor.* methods work on it). */\n  editable: boolean;\n}",
 "BlockSummary": "export interface BlockSummary {\n  id: string;\n  type: string;\n  text: string;\n  props?: Record<string, unknown>;\n  children?: BlockSummary[];\n}",
 "EditorSelection": "export interface EditorSelection {\n  text: string;\n  blockIds: string[];\n  cursorBlockId: string;\n}",
 "BlockDetail": "/** One block from editor.getBlock: the summary plus where it sits. */\nexport interface BlockDetail extends BlockSummary {\n  /** Parent block id (\"\" at the top level). */\n  parentId: string;\n  /** Previous sibling id (\"\" when first). */\n  prevId: string;\n  /** Next sibling id (\"\" when last). */\n  nextId: string;\n}",
 "OutlineItem": "export interface OutlineItem {\n  id: string;\n  text: string;\n  level: number;\n}",
 "EditorSnapshot": "export interface EditorSnapshot {\n  pageId: string;\n  title: string;\n  wordCount: number;\n  blockCount: number;\n  text: string;\n  outline: OutlineItem[];\n}",
 "PageBackgroundInfo": "/** Content facts about a page (pages.stats). Database pages also get `database`. */\n/** A page's background (behind the whole page, not the cover). */\nexport interface PageBackgroundInfo {\n  kind: \"color\" | \"gradient\" | \"image\" | \"ascii\";\n  value?: string;\n  ascii?: { scene: string; speed?: number; ink?: string; density?: \"fine\" | \"normal\" | \"large\"; still?: boolean; cursor?: boolean };\n  opacity?: number;\n  dim?: number;\n}",
 "PageStats": "export interface PageStats {\n  pageId: string;\n  title: string;\n  kind: \"page\" | \"folder\" | \"database\" | \"row\" | \"custom\";\n  icon: string;\n  parentId: string;\n  createdAt: string;\n  updatedAt: string;\n  /** 0 for top-level pages. */\n  depth: number;\n  childPages: number;\n  favorite: boolean;\n  /** The page is the one in focus. */\n  active: boolean;\n  /** Counted from the open editor (includes unsaved edits). */\n  open: boolean;\n  words: number;\n  characters: number;\n  charactersNoSpaces: number;\n  blocks: number;\n  paragraphs: number;\n  lines: number;\n  blockTypes: Record<string, number>;\n  headings: { level: number; text: string; blockId: string }[];\n  todos: { total: number; done: number; open: number };\n  links: { url: string; text: string }[];\n  pageLinks: { pageId: string; title: string }[];\n  databases: { id: string; title: string; blockId: string }[];\n  customBlocks: { kind: string; count: number }[];\n  images: number;\n  media: number;\n  files: number;\n  tables: number;\n  codeBlocks: number;\n  quotes: number;\n  readingMinutes: number;\n  speakingMinutes: number;\n  database?: { rows: number; properties: { id: string; name: string; type: string }[]; views: number; viewTypes: string[] };\n}",
 "WorkspaceStats": "export interface WorkspaceStats {\n  workspaceId: string | null;\n  workspaceName: string;\n  /** Every live item (pages, databases, rows, folders, custom). */\n  total: number;\n  pages: number;\n  databases: number;\n  rows: number;\n  folders: number;\n  custom: number;\n  topLevel: number;\n  favorites: number;\n  trashed: number;\n  maxDepth: number;\n  lastEdited: { pageId: string; title: string; updatedAt: string } | null;\n  /** With content: true — totals read from every page's text. */\n  content?: {\n    scanned: number;\n    words: number;\n    characters: number;\n    blocks: number;\n    todos: { total: number; done: number; open: number };\n    longest: { pageId: string; title: string; words: number }[];\n    readingMinutes: number;\n  };\n}",
 "AppState": "/** What the window shows right now (app.state). */\nexport interface AppState {\n  activePageId: string;\n  activeTitle: string;\n  focusedPaneId: string;\n  panes: {\n    id: string;\n    focused: boolean;\n    maximized: boolean;\n    activeTab: string;\n    tabs: { id: string; pageId: string; title: string; kind: \"home\" | \"page\" | \"web\" | \"folder\" | \"database\" | \"row\" | \"custom\"; active: boolean }[];\n  }[];\n  openTabs: number;\n  leftSidebar: { open: boolean; tab: string };\n  rightSidebar: { open: boolean; tab: string };\n  assistantOpen: boolean;\n  /** Open overlay (\"palette\", \"settings\", …) or \"\". */\n  overlay: string;\n  theme: \"light\" | \"dark\";\n  online: boolean;\n  window: { width: number; height: number };\n  workspaceId: string | null;\n  history: { canGoBack: boolean; canGoForward: boolean };\n}",
 "PageInfo": "export interface PageInfo {\n  id: string;\n  title: string;\n  icon: string;\n  cover: string;\n  kind: \"page\" | \"folder\" | \"database\" | \"row\" | \"custom\";\n  /** Custom node type id, for kind \"custom\" (see nodes.listTypes). */\n  nodeType?: string;\n  parentId: string;\n  /** For rows: the database they belong to. */\n  databaseId?: string;\n  createdAt: string;\n  updatedAt: string;\n  deleted?: boolean;\n}",
 "PageContent": "export interface PageContent {\n  page: PageInfo;\n  format: \"markdown\" | \"text\";\n  content: string;\n  /** Child pages (and database rows) directly under this page. */\n  children: PageInfo[];\n}",
 "DatabaseInfo": "export interface DatabaseInfo {\n  id: string;\n  title: string;\n  parentId: string;\n  rowCount: number;\n  properties: string[];\n}",
 "DatabasePropertyInfo": "export interface DatabasePropertyInfo {\n  id: string;\n  name: string;\n  type: string;\n  options?: { id: string; name: string; color: string }[];\n  /** Number properties (and number formulas): number | commas | percent | dollar | euro | pound | yen. */\n  format?: string;\n  /** Formula properties: the formula source. */\n  formula?: string;\n  /** Formula properties: the type the results have (number, text, checkbox, date). */\n  resultType?: string;\n  /** Date and date-formula display: relative | short | long | iso. */\n  dateFormat?: string;\n  /** Formula properties: why the formula fails, if it does. */\n  error?: string;\n  /** Number properties (and number formulas): how the value is shown, when not as a plain number. */\n  display?: { style: \"number\" | \"bar\" | \"ring\" | \"rating\" | \"heat\"; color?: string; max?: number; showNumber?: boolean };\n}",
 "DatabaseSchemaInfo": "export interface DatabaseSchemaInfo {\n  databaseId: string;\n  title: string;\n  titleName: string;\n  /** Present (true) when the database is locked: row writes are refused. */\n  locked?: boolean;\n  properties: DatabasePropertyInfo[];\n  views: { id: string; name: string; type: string }[];\n}",
 "DatabaseFilterNode": "/** A filter rule, or a nested and/or group of rules (advanced filters). */\nexport type DatabaseFilterNode =\n  | { id: string; property: string; op: string; value?: unknown }\n  | { id: string; mode: \"and\" | \"or\"; items: DatabaseFilterNode[] };\n\n/** Chart view settings; property ids are returned as names. */",
 "DatabaseChartInfo": "export interface DatabaseChartInfo {\n  kind?: \"bar\" | \"column\" | \"line\" | \"area\" | \"pie\" | \"donut\" | \"scatter\" | \"funnel\" | \"radar\" | \"heatmap\" | \"number\";\n  x?: string;\n  dateBucket?: \"day\" | \"week\" | \"month\" | \"quarter\" | \"year\";\n  aggregate?: \"count\" | \"countValues\" | \"countUnique\" | \"sum\" | \"average\" | \"median\" | \"min\" | \"max\";\n  y?: string;\n  series?: string;\n  stacked?: boolean;\n  normalize?: boolean;\n  cumulative?: boolean;\n  sort?: \"default\" | \"label\" | \"labelDesc\" | \"value\" | \"valueDesc\";\n  limit?: number;\n  omitEmpty?: boolean;\n  smooth?: boolean;\n  labels?: boolean;\n  legend?: boolean;\n  grid?: boolean;\n  palette?: string;\n  height?: number;\n  goal?: number;\n  yMin?: number;\n  yMax?: number;\n  format?: string;\n  title?: string;\n  zoom?: boolean;\n  zoomSlider?: boolean;\n  xTitle?: string;\n  yTitle?: string;\n  xLabels?: boolean;\n  yLabels?: boolean;\n  labelAngle?: number;\n  logScale?: boolean;\n  labelContent?: \"value\" | \"percent\" | \"name\" | \"nameValue\" | \"namePercent\";\n  labelPosition?: \"inside\" | \"outside\";\n  colorBy?: \"category\" | \"single\";\n  color?: string;\n  curve?: \"straight\" | \"smooth\" | \"step\";\n  points?: boolean;\n  gradient?: boolean;\n  donutWidth?: number;\n  other?: boolean;\n  aggregate2?: \"count\" | \"countValues\" | \"countUnique\" | \"sum\" | \"average\" | \"median\" | \"min\" | \"max\";\n  /** Property name. */\n  y2?: string;\n  legendPosition?: \"top\" | \"bottom\" | \"left\" | \"right\";\n  tooltip?: \"group\" | \"item\" | \"off\";\n  goalLabel?: string;\n  emptyText?: string;\n}",
 "DatabaseViewInfo": "export interface DatabaseViewInfo {\n  databaseId: string;\n  id: string;\n  name: string;\n  type: \"table\" | \"board\" | \"gallery\" | \"list\" | \"calendar\" | \"chart\" | \"custom\";\n  filters: { id: string; property: string; op: string; value?: unknown }[];\n  filterMode: \"and\" | \"or\";\n  /** Advanced filter tree, combined (AND) with `filters`. */\n  advanced?: { mode: \"and\" | \"or\"; items: DatabaseFilterNode[] };\n  sorts: { property: string; direction: \"asc\" | \"desc\" }[];\n  /** Visible properties, in order (the title column first). */\n  visible: string[];\n  hidden: string[];\n  groupBy?: string;\n  hiddenGroups?: string[];\n  collapsedGroups?: string[];\n  hideEmptyGroups?: boolean;\n  colorColumns?: boolean;\n  dateProperty?: string;\n  cardPreview?: \"cover\" | \"none\";\n  cardSize?: \"small\" | \"medium\" | \"large\";\n  wrap?: boolean;\n  widths?: Record<string, number>;\n  calcs?: Record<string, string>;\n  showFilterBar?: boolean;\n  /** Rows shown before \"Load more\". */\n  limit?: number;\n  showIcons?: boolean;\n  /** Tab icon (emoji or icon value). */\n  icon?: string;\n  /** Set when a database block created this view for itself: the block id. It shows only in that block. */\n  owner?: string;\n  /** Where row pages open: modal (default) | side | tab | current. */\n  openIn?: \"modal\" | \"side\" | \"tab\" | \"current\";\n  rowNumbers?: boolean;\n  chart?: DatabaseChartInfo;\n  /** Custom views: the HTML/CSS/JS rendered in a sandboxed frame. */\n  custom?: { html: string; height?: number };\n}",
 "DatabaseRowInfo": "export interface DatabaseRowInfo {\n  id: string;\n  title: string;\n  /** Values keyed by property name; select options are returned by name; formulas hold their result. */\n  values: Record<string, unknown>;\n  updatedAt: string;\n  /** Formula errors for this row, by property name. */\n  errors?: Record<string, string>;\n}",
 "WorkspaceInfo": "export interface WorkspaceInfo {\n  id: string;\n  name: string;\n  pageCount: number;\n  current: boolean;\n}",
 "TabInfo": "export interface TabInfo {\n  id: string;\n  title: string;\n  kind: \"page\" | \"home\" | \"web\";\n  paneId: string;\n  active: boolean;\n}",
 "PaneInfo": "export interface PaneInfo {\n  id: string;\n  tabs: string[];\n  activeTabId: string;\n  focused: boolean;\n  maximized: boolean;\n}",
 "LayoutInfo": "export interface LayoutInfo {\n  panes: PaneInfo[];\n  /** Nested split tree: { type: \"pane\", id } | { type: \"split\", dir, sizes, children }. */\n  tree: unknown;\n  leftOpen: boolean;\n  rightOpen: boolean;\n  railOpen: boolean;\n  leftWidth: number;\n  rightWidth: number;\n  leftTab: string;\n  rightTab: string;\n}",
 "SearchHitInfo": "export interface SearchHitInfo {\n  pageId: string;\n  title: string;\n  snippet: string;\n  updatedAt: string;\n}",
 "Preferences": "export interface Preferences {\n  theme: \"light\" | \"dark\" | \"system\";\n  editorFont: \"serif\" | \"sans\";\n  fontSize: number;\n  lineHeight: number;\n  pageWidth: number;\n  fullWidth: boolean;\n  autosaveDelay: number;\n  spellcheck: boolean;\n  reduceMotion: boolean;\n  showStats: boolean;\n}",
 "CssSnippet": "export interface CssSnippet {\n  id: string;\n  label: string;\n  css: string;\n  enabled: boolean;\n}",
 "ComponentStyle": "export interface ComponentStyle {\n  css?: string;\n  rules?: string;\n  hidden?: boolean;\n}",
 "Look": "export interface Look {\n  tokens: { light: Record<string, string>; dark: Record<string, string> };\n  components: Record<string, ComponentStyle>;\n  css: CssSnippet[];\n}",
 "Customizations": "/** The base look plus every layer. */\nexport interface Customizations extends Look {\n  version: 2;\n  layers: LayerInfo[];\n  sidebar?: { groups: { id: string; tabs: string[]; active: string; size: number }[] };\n}",
 "LayerInfo": "/** A switchable bundle of customizations (see appearance.listLayers). */\nexport interface LayerInfo extends Look {\n  id: string;\n  name: string;\n  description?: string;\n  source: \"assistant\" | \"user\" | \"plugin\";\n  enabled: boolean;\n  createdAt: number;\n  updatedAt: number;\n  permissions: string[];\n  chatId?: string;\n  pluginId?: string;\n  sidebarTabs: SidebarTabDefinition[];\n  statusWidgets: StatusWidgetDefinition[];\n  blockTypes: BlockTypeDefinition[];\n  nodeTypes: NodeTypeDefinition[];\n}",
 "TokenInfo": "export interface TokenInfo {\n  name: string;\n  group: \"color\" | \"font\" | \"shape\" | \"layout\";\n  description: string;\n  light: string;\n  dark: string;\n}",
 "ComponentInfo": "export interface ComponentInfo {\n  id: string;\n  label: string;\n  selector: string;\n  description: string;\n}",
 "CommandInfo": "export interface CommandInfo {\n  id: string;\n  title: string;\n  category: string;\n  description?: string;\n  shortcut?: string;\n}",
 "WebSearchResult": "export interface WebSearchResult {\n  query: string;\n  engine: string;\n  results: { title: string; url: string; snippet: string }[];\n}",
 "WebPage": "export interface WebPage {\n  url: string;\n  finalUrl: string;\n  title: string;\n  contentType: string;\n  /** Readable text (Markdown-ish) extracted from the page. */\n  content: string;\n  truncated: boolean;\n  links?: { text: string; url: string }[];\n}",
 "HttpResponse": "export interface HttpResponse {\n  status: number;\n  statusText: string;\n  headers: Record<string, string>;\n  /** Body as text, or base64 when `encoding` is \"base64\". */\n  body: string;\n  encoding: \"text\" | \"base64\";\n  url: string;\n}",
 "PluginInfo": "export interface PluginInfo {\n  id: string;\n  name: string;\n  version: string;\n  author: string;\n  description: string;\n  enabled: boolean;\n  source: string;\n  permissions: string[];\n  problem?: string;\n}",
 "PluginDocsResult": "/** plugins.docs: the plugin guide, method reference and types, for writing plugins. */\nexport interface PluginDocsResult {\n  /** Matching guide sections (topic), with their text. */\n  sections?: { title: string; text: string }[];\n  /** Method reference (method or namespace), including plugin-only methods. */\n  methods?: { name: string; summary: string; details?: string; permission: string | null; callers: string[]; params?: unknown; returns: string }[];\n  /** Type definitions (type, or the types a looked-up method returns). */\n  types?: Record<string, string>;\n  /** With no arguments: what can be looked up. */\n  index?: { sections: string[]; namespaces: Record<string, number>; events: string[]; permissions: string[] };\n  hint?: string;\n}",
 "PluginSourceInfo": "export interface PluginSourceInfo {\n  manifest: Record<string, unknown>;\n  code: string;\n  styles: string;\n}",
 "PanelAction": "export interface PanelAction {\n  id: string;\n  label: string;\n  primary?: boolean;\n}",
 "PluginManifest": "/** manifest.json — see docs/plugins/manifest.md. */\nexport interface PluginManifest {\n  /** Reverse-domain id, e.g. \"com.example.word-goal\". Never changes between versions. */\n  id: string;\n  name: string;\n  /** Semver, e.g. \"1.2.0\". Must match the GitHub release tag (with or without \"v\"). */\n  version: string;\n  /** SDK the plugin was built against, e.g. \"2.0.0\". */\n  sdkVersion: string;\n  /** Oldest Noteral version the plugin works with. */\n  minAppVersion?: string;\n  description?: string;\n  author?: string;\n  authorUrl?: string;\n  /** \"owner/name\" of the GitHub repository that publishes releases. */\n  repo?: string;\n  /** Bundled script, usually \"main.js\". */\n  entry: string;\n  permissions: string[];\n  contributes?: {\n    commands?: Array<{ id: string; title: string; description?: string; keywords?: string }>;\n    statusItems?: Array<{ id: string; label: string }>;\n    panels?: Array<{ id: string; title: string }>;\n  };\n}",
 "StatusOptions": "export interface StatusOptions {\n  /** Tooltip shown on hover. */\n  title?: string;\n}",
 "ViewContent": "/** Content of a sidebar tab or similar surface: Markdown with buttons, or an HTML view. */\nexport interface ViewContent {\n  markdown?: string;\n  actions?: PanelAction[];\n  html?: string;\n}",
 "SidebarTabDefinition": "export interface SidebarTabDefinition {\n  id: string;\n  title: string;\n  icon?: string;\n  view: ViewContent;\n}",
 "StatusWidgetDefinition": "export interface StatusWidgetDefinition {\n  id: string;\n  text?: string;\n  tooltip?: string;\n  icon?: string;\n  html?: string;\n  width?: number;\n  side: \"left\" | \"right\";\n  order: number;\n  command?: string;\n}",
 "BlockTypeDefinition": "export interface BlockTypeDefinition {\n  type: string;\n  title: string;\n  description?: string;\n  icon?: string;\n  keywords?: string[];\n  html: string;\n  defaultData?: unknown;\n  height?: number;\n}",
 "NodeTypeDefinition": "export interface NodeTypeDefinition {\n  type: string;\n  title: string;\n  description?: string;\n  icon?: string;\n  html: string;\n  defaultData?: unknown;\n}",
 "ContributionOwnerInfo": "export interface ContributionOwnerInfo {\n  kind: \"plugin\" | \"layer\";\n  id: string;\n  name: string;\n}",
 "SidebarTabInfo": "export interface SidebarTabInfo {\n  /** Key used by sidebar.openTab / setLayout: built-in id or \"<owner kind>:<owner id>:<tab id>\". */\n  key: string;\n  id: string;\n  title: string;\n  icon?: string;\n  builtin: boolean;\n  owner?: ContributionOwnerInfo;\n  kind: \"builtin\" | \"markdown\" | \"html\";\n}",
 "SidebarInfo": "export interface SidebarInfo {\n  open: boolean;\n  width: number;\n  groups: { tabs: string[]; active: string; size: number }[];\n  tabs: SidebarTabInfo[];\n}",
 "StatusWidgetInfo": "export interface StatusWidgetInfo {\n  /** Use this key with statusBar.setItem / statusBar.configure (built-ins: \"builtin:<id>\"). */\n  key: string;\n  id: string;\n  /** Where it shows now (after the layout). */\n  side: \"left\" | \"center\" | \"right\";\n  order: number;\n  builtin: boolean;\n  text?: string;\n  kind: \"builtin\" | \"text\" | \"html\";\n  owner?: ContributionOwnerInfo;\n  /** Hidden by the layout (built-ins \"local\", \"page\" and \"clock\" start hidden). */\n  hidden?: boolean;\n  width?: number | string;\n}",
 "StatusItemLayoutInfo": "export interface StatusItemLayoutInfo {\n  hidden?: boolean;\n  side?: \"left\" | \"center\" | \"right\";\n  order?: number;\n  width?: number | string;\n  align?: \"start\" | \"center\" | \"end\";\n}",
 "StatusBarLayoutInfo": "export interface StatusBarLayoutInfo {\n  hidden?: boolean;\n  separator: \"none\" | \"line\" | \"dot\" | \"slash\" | \"space\";\n  gap?: number;\n  height?: number;\n  padding?: number;\n  fontSize?: number;\n  items: Record<string, StatusItemLayoutInfo>;\n  /** Every item with its effective placement. */\n  widgets: StatusWidgetInfo[];\n}",
 "BlockTypeInfo": "export interface BlockTypeInfo {\n  type: string;\n  title: string;\n  description?: string;\n  icon?: string;\n  owner: ContributionOwnerInfo;\n}",
 "NodeTypeInfo": "export interface NodeTypeInfo {\n  type: string;\n  title: string;\n  description?: string;\n  icon?: string;\n  /** \"full\": the view is the whole page. \"page\": a page head above the view. */\n  layout: \"full\" | \"page\";\n  owner: ContributionOwnerInfo;\n}",
 "MenuItemInfo": "export interface MenuItemInfo {\n  key: string;\n  id: string;\n  menu: \"page\" | \"tree\" | \"block\" | \"tab\" | \"status\";\n  title: string;\n  icon?: string;\n  command: string;\n  danger?: boolean;\n  owner: ContributionOwnerInfo;\n}",
 "SettingFieldInfo": "export interface SettingFieldInfo {\n  key: string;\n  type: \"toggle\" | \"text\" | \"textarea\" | \"number\" | \"slider\" | \"select\" | \"color\";\n  label: string;\n  description?: string;\n  default?: unknown;\n  options?: { value: string; label: string }[];\n  min?: number;\n  max?: number;\n  step?: number;\n  placeholder?: string;\n  section?: string;\n}",
 "HomeViewSummary": "export interface HomeViewSummary {\n  id: string;\n  name: string;\n  kind: \"template\" | \"custom\";\n  isDefault: boolean;\n  widgets?: number;\n  background: string;\n}",
 "HomeWidgetInfo": "export interface HomeWidgetInfo {\n  id: string;\n  type: string;\n  x: number;\n  y: number;\n  w: number;\n  h: number;\n  title?: string;\n  [key: string]: unknown;\n}",
 "HomeViewInfo": "export interface HomeViewInfo {\n  id: string;\n  name: string;\n  title: string;\n  width: \"narrow\" | \"wide\" | \"full\";\n  gap: \"tight\" | \"normal\" | \"roomy\";\n  cards: \"glass\" | \"solid\" | \"outline\" | \"flat\";\n  radius: number;\n  shadow: \"none\" | \"soft\" | \"lifted\";\n  font: \"serif\" | \"sans\" | \"mono\";\n  valign: \"top\" | \"center\";\n  accent?: string;\n  css?: string;\n  widgets: HomeWidgetInfo[];\n  /** Background presets that home.setBackground accepts. */\n  backgrounds: string[];\n}",
 "HomeWidgetTypeInfo": "export interface HomeWidgetTypeInfo {\n  type: string;\n  label: string;\n  description: string;\n  w: number;\n  h: number;\n}",
 "AskResult": "export interface AskResult {\n  /** The typed answer, or the chosen labels joined with \", \". */\n  answer: string;\n  choices: string[];\n  cancelled: boolean;\n}",
 "LogEntryInfo": "export interface LogEntryInfo {\n  at: number;\n  level: \"info\" | \"warn\" | \"error\";\n  message: string;\n}",
 "PluginTestResult": "export interface PluginTestResult {\n  ok: boolean;\n  status: \"ready\" | \"failed\" | \"timeout\";\n  error?: string;\n  logs: { level: string; message: string }[];\n  commands: string[];\n  contributions: { sidebarTabs: string[]; statusWidgets: string[]; blockTypes: string[]; nodeTypes: string[]; menuItems: string[]; settings: string[]; overlays: string[]; propertyTypes: string[]; panels: string[]; statusItems: string[] };\n  /** App API methods the code called. */\n  calls: string[];\n  /** Write calls that were skipped during the test. */\n  skipped: string[];\n}",
 "PluginInstallResult": "export interface PluginInstallResult extends PluginInfo {\n  test?: PluginTestResult;\n  health: { status: \"ready\" | \"failed\" | \"starting\" | \"stopped\"; error?: string; logs: { level: string; message: string }[] };\n}",
 "SourceEntry": "/** Something with editable text, from source.list (assistant). */\nexport interface SourceEntry {\n  /** Pass to source.get / source.edit, e.g. \"status:pomodoro\", \"home:<viewId>/<widgetId>\". */\n  target: string;\n  kind: \"sidebar\" | \"status\" | \"block\" | \"node\" | \"css\" | \"component\" | \"home\" | \"homeview\" | \"plugin\";\n  title: string;\n  /** Layer id (\"base\" = the app's own customizations), plugin id, or \"home\". */\n  owner: string;\n  /** Text fields and their length in characters. */\n  fields: Record<string, number>;\n  /** False for plugin-owned items: change them with plugins.edit. */\n  editable: boolean;\n}",
 "StorageEntryInfo": "/** One key in a plugin's private storage (storage.list). */\nexport interface StorageEntryInfo {\n  key: string;\n  /** Size of the stored JSON in bytes. */\n  size: number;\n  /** ISO time of the last write. */\n  modified: string;\n}",
 "StorageUsageInfo": "/** How much a plugin stores across all scopes (storage.usage). */\nexport interface StorageUsageInfo {\n  keys: number;\n  bytes: number;\n  maxBytes: number;\n}",
 "PluginApiInfo": "/** A running plugin and the methods it exposes to other plugins (plugins.list). */\nexport interface PluginApiInfo {\n  id: string;\n  name: string;\n  version: string;\n  /** Methods callable with plugins.call; empty when the plugin exposes none. */\n  methods: string[];\n}",
 "SuggestItem": "/** One row a suggester returns (Plugin.registerSuggester). */\nexport interface SuggestItem {\n  /** Stable id, passed back to onSelect. */\n  id?: string;\n  title: string;\n  /** Second line, e.g. a path or a description. */\n  subtitle?: string;\n  /** Group heading in the menu. */\n  group?: string;\n  /** Text inserted in place of the trigger and query. Defaults to title. Ignored when onSelect handles it. */\n  insert?: string;\n  /** Turn the inserted text into a link: an https URL or noteral://page/<pageId>. */\n  link?: string;\n  /** Any JSON you want back in onSelect. */\n  data?: unknown;\n}",
 "SuggestContext": "/** Where a suggester was opened. */\nexport interface SuggestContext {\n  /** What was typed after the trigger. */\n  query: string;\n  trigger: string;\n  pageId: string | null;\n  blockId: string | null;\n}",
 "PropertyCellContext": "/** What a custom property type's template, renderer function and editor view receive. */\nexport interface PropertyCellContext {\n  /** The cell's value (for stored `{ value, ... }` objects, their `value`). */\n  value: unknown;\n  /** The stored value as is. */\n  raw: unknown;\n  /** Plain-text form of the value. */\n  text: string;\n  empty: boolean;\n  /** The property's options (the type's config fields, defaults filled in). */\n  config: Record<string, unknown>;\n  property: { id: string; name: string; type: string };\n  row: { id: string; title: string };\n  /** Shown in a card or list (less room). */\n  compact: boolean;\n}",
 "PropertyConfigField": "/** A config field of a custom property type, edited in the property's menu. */\nexport interface PropertyConfigField {\n  key: string;\n  type: \"toggle\" | \"text\" | \"textarea\" | \"number\" | \"slider\" | \"select\" | \"color\";\n  label: string;\n  description?: string;\n  default?: unknown;\n  options?: { value: string; label: string }[];\n  min?: number;\n  max?: number;\n  step?: number;\n  placeholder?: string;\n}",
 "PropertyTypeDefinition": "/** this.registerPropertyType(...) in the SDK. */\nexport interface PropertyTypeDefinition {\n  /** Stored in databases: keep it stable. */\n  type: string;\n  title?: string;\n  icon?: string;\n  description?: string;\n  /** How values sort, filter, group and calculate. Default \"text\". */\n  valueType?: \"text\" | \"number\" | \"checkbox\" | \"date\";\n  /** A cell template string, or a function (runs in the plugin) returning the cell's HTML. */\n  render?: string | ((context: PropertyCellContext) => string | Promise<string>);\n  css?: string;\n  /** HTML view to edit a value in a popover (props: PropertyCellContext). */\n  editor?: string;\n  editorWidth?: number;\n  editorHeight?: number;\n  config?: PropertyConfigField[];\n  defaultValue?: unknown;\n  align?: \"start\" | \"center\" | \"end\";\n}",
 "OverlayDefinition": "/** this.addOverlay(...) in the SDK / ui.setOverlay. */\nexport interface OverlayDefinition {\n  id: string;\n  html: string;\n  title?: string;\n  position?: \"top-left\" | \"top\" | \"top-right\" | \"left\" | \"center\" | \"right\" | \"bottom-left\" | \"bottom\" | \"bottom-right\" | \"full\";\n  x?: number;\n  y?: number;\n  width?: number | string;\n  height?: number | string;\n  interactive?: boolean;\n  draggable?: boolean;\n  chrome?: boolean;\n  opacity?: number;\n  stack?: \"app\" | \"top\";\n  hidden?: boolean;\n  order?: number;\n  data?: unknown;\n}",
 "PageEventInfo": "/** Payload of page:created, page:deleted (and the base of page:renamed / page:moved). */\nexport interface PageEventInfo {\n  pageId: string;\n  title: string;\n  parentId: string | null;\n  kind: string;\n}"
};
